* { box-sizing: border-box; }
:root { --ink: #172554; --muted: #475569; --line: #cbd5e1; --surface: #fff; --accent: #1d4ed8; }
body { margin: 0; font: 1rem/1.6 system-ui, sans-serif; color: var(--ink); background: #f8fafc; }
.site-header { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: 1.25rem max(1rem, calc((100vw - 74rem) / 2)); background: white; }
.site-header nav { display: flex; gap: 1rem; flex-wrap: wrap; }
.brand { font-weight: 800; text-decoration: none; }
.page-shell { width: min(calc(100% - 2rem), 74rem); margin-inline: auto; }
.hero { padding-block: clamp(2.5rem, 6vw, 5rem); text-align: center; }
h1 { max-width: 15ch; margin: .25rem auto 1rem; font-size: clamp(2.2rem, 5vw, 4rem); line-height: 1.05; }
.pricing-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem; align-items: stretch; }
.plan-card { position: relative; padding: 1.5rem; border: 1px solid var(--line); border-radius: 1rem; background: var(--surface); }
.plan-card--featured { border: 2px solid var(--accent); box-shadow: 0 1rem 2.5rem rgb(23 37 84 / .1); }
.plan-badge { display: inline-block; padding: .25rem .5rem; border-radius: 99px; background: #dbeafe; color: #1e3a8a; font-size: .8rem; font-weight: 800; }
.plan-price { font-size: 2.3rem; font-weight: 800; margin-block: 1rem; }
.plan-price span { font-size: .9rem; color: var(--muted); font-weight: 500; }
.feature-list { padding-inline-start: 1.25rem; min-height: 7rem; }
.feature-list li + li { margin-block-start: .5rem; }
.button { display: inline-block; border: 2px solid var(--accent); border-radius: .5rem; padding: .7rem 1rem; background: var(--accent); color: white; font: inherit; font-weight: 700; text-decoration: none; }
.button-secondary { background: transparent; color: var(--accent); }
.section { padding-block: 3rem; }
:focus-visible { outline: 3px solid #0f766e; outline-offset: 3px; }
@media (max-width: 54rem) { .pricing-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } .plan-card--featured { order: -1; } }
@media (max-width: 38rem) { .pricing-grid { grid-template-columns: minmax(0, 1fr); } .plan-card--featured { order: 0; } .site-header { align-items: flex-start; flex-direction: column; } }
